import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def calculate_an(n):
    # a_n = 6^n + 2^n + 3^n - 1
    return 6**n + 2**n + 3**n - 1

results = {}
for n in range(1, 11):
    a_n = calculate_an(n)
    factors = prime_factorization(a_n)
    results[n] = {"value": a_n, "factors": factors}

for n in range(1, 11):
    value = results[n]["value"]
    factors = results[n]["factors"]
    factor_str = " * ".join([f"{p}^{e}" for p, e in factors.items()])
    print(f"n={n}: a_n = {value}, Prime Factorization: {factor_str}")

def calculate_a_n(n):
    # a_n = 6^n + 2^n + 3^n - 1
    return 6**n + 2**n + 3**n - 1

def check_mod_5(n):
    a_n = calculate_a_n(n)
    return a_n % 5

# Check n=1 to n=7 to look for a pattern
for n in range(1, 8):
    print(f"a_{n} mod 5: {check_mod_5(n)}")

